     1	import { DOCUMENT } from '@angular/common';
     2	import {
     3	  afterNextRender,
     4	  computed,
     5	  inject,
     6	  Injectable,
     7	  signal,
     8	} from '@angular/core';
     9	import { GAME_SUPPORT } from './game-support';
    10	import { PlayBillingService, TipProduct } from './play-billing.service';
    11	import { isTwaSession } from './twa-session';
    12	
    13	/** What happened to the last tip, for a line under the tip buttons. */
    14	export type TipNotice = 'thanks' | 'failed' | null;
    15	
    16	export const PRODUCT_LOAD_ATTEMPTS = 3;
    17	export const PRODUCT_LOAD_RETRY_MS = 2000;
    18	
    19	export function buyMeACoffeeUrl(handle: string): string {
    20	  return `https://buymeacoffee.com/${encodeURIComponent(handle)}`;
    21	}
    22	
    23	/**
    24	 * How a player can pay for the game where they play it: the Buy Me a
    25	 * Coffee page on the web, the Play tip products inside the Play Store app,
    26	 * which allows tips only through Play Billing - or nothing, inside the
    27	 * shell. Decided after the first render, when the referrer tells the app
    28	 * from the web.
    29	 */
    30	@Injectable({ providedIn: 'root' })
    31	export class GameSupport {
    32	  private readonly options = inject(GAME_SUPPORT);
    33	  private readonly billing = inject(PlayBillingService);
    34	  private readonly document = inject(DOCUMENT);
    35	
    36	  private readonly where = signal<'web' | 'app' | null>(null);
    37	  private readonly products = signal<readonly TipProduct[]>([]);
    38	  private readonly buying = signal<string | null>(null);
    39	  private readonly lastTip = signal<TipNotice>(null);
    40	
    41	  /** The Buy Me a Coffee page, null in the app or without a handle. */
    42	  public readonly url = computed(() => {
    43	    const handle = this.options?.buyMeACoffeeHandle;
    44	    return this.where() === 'web' && handle ? buyMeACoffeeUrl(handle) : null;
    45	  });
    46	  /** The tips the Play Store sells, empty outside the app. */
    47	  public readonly tipProducts = this.products.asReadonly();
    48	  public readonly available = computed(
    49	    () => this.url() !== null || this.products().length > 0
    50	  );
    51	  /** The tip whose purchase is open, null while none is. */
    52	  public readonly busyTip = this.buying.asReadonly();
    53	  public readonly tipNotice = this.lastTip.asReadonly();
    54	
    55	  public constructor() {
    56	    const options = this.options;
    57	    if (!options) return;
    58	    afterNextRender(() => {
    59	      const app = isTwaSession(this.document, options.androidPackage);
    60	      this.where.set(app ? 'app' : 'web');
    61	      if (app) void this.loadProducts();
    62	    });
    63	  }
    64	
    65	  public async tip(productId: string): Promise<void> {
    66	    if (this.buying()) return;
    67	    this.buying.set(productId);
    68	    this.lastTip.set(null);
    69	    try {
    70	      const outcome = await this.billing.buy(productId);
    71	      if (outcome === 'purchased') this.lastTip.set('thanks');
    72	    } catch {
    73	      this.lastTip.set('failed');
    74	    } finally {
    75	      this.buying.set(null);
    76	    }
    77	  }
    78	
    79	  private async loadProducts(): Promise<void> {
    80	    const ids = this.options?.playTipProductIds ?? [];
    81	    if (ids.length === 0) return;
    82	    // Right after the start the app's billing bridge may not be bound yet.
    83	    for (let attempt = 1; ; attempt++) {
    84	      const products = await this.billing.loadProducts(ids);
    85	      if (products) {
    86	        this.products.set(products);
    87	        // Now that billing answers, tips a closed app left unconsumed.
    88	        await this.billing.consumePending(ids);
    89	        return;
    90	      }
    91	      if (attempt === PRODUCT_LOAD_ATTEMPTS) return;
    92	      await new Promise((done) =>
    93	        setTimeout(done, PRODUCT_LOAD_RETRY_MS * attempt)
    94	      );
    95	    }
    96	  }
    97	}
