     1	import { DOCUMENT } from '@angular/common';
     2	import { computed, inject, Injectable, signal } from '@angular/core';
     3	import { GAME_SUPPORT } from './game-support';
     4	
     5	/** The slice of an IAB TCF v2.2 TCData object the game waits for. */
     6	export interface TcData {
     7	  readonly eventStatus: 'tcloaded' | 'cmpuishown' | 'useractioncomplete';
     8	  readonly gdprApplies?: boolean;
     9	}
    10	
    11	export type TcfApi = (
    12	  command: 'addEventListener',
    13	  version: 2,
    14	  callback: (tcData: TcData, success: boolean) => void
    15	) => void;
    16	
    17	export type AdsWindow = Window & {
    18	  adsbygoogle?: object[];
    19	  __tcfapi?: TcfApi;
    20	  googlefc?: {
    21	    callbackQueue?: Record<string, () => void>[];
    22	    showRevocationMessage?: () => void;
    23	  };
    24	};
    25	
    26	export const AD_SCRIPT_ID = 'bacteria-game-ads';
    27	
    28	export const TCF_POLL_INTERVAL_MS = 200;
    29	const TCF_POLL_MAX_TRIES = 150;
    30	
    31	/**
    32	 * The AdSense script and the consent it waits for. The script also brings
    33	 * the consent banner (Google Privacy & Messaging, a TCF v2.2 CMP), so it
    34	 * loads with the app; the ad slots stay empty until the player has made a
    35	 * choice. Whether the ads may be personalised AdSense reads from that
    36	 * choice itself.
    37	 */
    38	@Injectable({ providedIn: 'root' })
    39	export class GameAds {
    40	  private readonly options = inject(GAME_SUPPORT)?.ads ?? null;
    41	  private readonly document = inject(DOCUMENT);
    42	  private readonly window = this.document.defaultView as AdsWindow | null;
    43	
    44	  private readonly answered = signal(false);
    45	  private started = false;
    46	
    47	  /** The ad unit the screens show, null without ads. */
    48	  public readonly ad = this.options?.slot ? this.options : null;
    49	  /**
    50	   * True once the consent banner reported a choice, or that none is
    51	   * needed - and with it, that the banner is there to open again.
    52	   */
    53	  public readonly consentAnswered = this.answered.asReadonly();
    54	  public readonly ready = computed(() => this.ad !== null && this.answered());
    55	
    56	  public start(): void {
    57	    if (!this.ad || !this.window || this.started) return;
    58	    this.started = true;
    59	    if (!this.document.getElementById(AD_SCRIPT_ID)) {
    60	      const script = this.document.createElement('script');
    61	      script.id = AD_SCRIPT_ID;
    62	      script.async = true;
    63	      script.crossOrigin = 'anonymous';
    64	      script.src = `https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=${encodeURIComponent(this.ad.client)}`;
    65	      this.document.head.appendChild(script);
    66	    }
    67	    // The script installs `__tcfapi` once it has loaded. Without it - an
    68	    // ad blocker, no consent message set up - no ads are asked for.
    69	    if (this.listen()) return;
    70	    let tries = 0;
    71	    const poll = setInterval(() => {
    72	      if (this.listen() || ++tries >= TCF_POLL_MAX_TRIES) clearInterval(poll);
    73	    }, TCF_POLL_INTERVAL_MS);
    74	  }
    75	
    76	  /** Fills an `<ins class="adsbygoogle">` that is in the page. */
    77	  public fill(): void {
    78	    if (!this.window) return;
    79	    (this.window.adsbygoogle ??= []).push({});
    80	  }
    81	
    82	  /**
    83	   * Opens the consent banner again. The choice made before holds until the
    84	   * player completes a new one.
    85	   */
    86	  public openConsentSettings(): void {
    87	    const window = this.window;
    88	    if (!window) return;
    89	    const googlefc = (window.googlefc ??= {});
    90	    (googlefc.callbackQueue ??= []).push({
    91	      CONSENT_DATA_READY: () => window.googlefc?.showRevocationMessage?.(),
    92	    });
    93	  }
    94	
    95	  private listen(): boolean {
    96	    const tcfApi = this.window?.__tcfapi;
    97	    if (typeof tcfApi !== 'function') return false;
    98	    tcfApi('addEventListener', 2, (tcData, success) => {
    99	      if (
   100	        success &&
   101	        (tcData.gdprApplies === false ||
   102	          tcData.eventStatus === 'tcloaded' ||
   103	          tcData.eventStatus === 'useractioncomplete')
   104	      ) {
   105	        this.answered.set(true);
   106	      }
   107	    });
   108	    return true;
   109	  }
   110	}
