     1	const TWA_SESSION_KEY = 'bacteria-game.twa';
     2	
     3	/**
     4	 * The `source` the Play Store app's launch URL carries (`build.gradle.kts`):
     5	 * the WebView fallback sends no referrer, and other apps' referrers say
     6	 * nothing about this one.
     7	 */
     8	export const APP_LAUNCH_SOURCE = 'twa';
     9	
    10	/**
    11	 * Whether the game runs inside the Play Store app with the given package:
    12	 * launched with `?source=twa`, or opened from a link by Chrome, which
    13	 * then sends the referrer `android-app://<package>`. A reload inside the app
    14	 * loses both, hence the flag in the session storage.
    15	 */
    16	export function isTwaSession(document: Document, appPackage: string): boolean {
    17	  const storage = document.defaultView?.sessionStorage;
    18	  const source = new URLSearchParams(document.location.search).get('source');
    19	  const referrer = document.referrer.replace(/\/$/, '');
    20	  if (
    21	    source === APP_LAUNCH_SOURCE ||
    22	    referrer === `android-app://${appPackage}`
    23	  ) {
    24	    try {
    25	      storage?.setItem(TWA_SESSION_KEY, '1');
    26	    } catch {
    27	      // Storage blocked: the referrer or the query still covers this page load.
    28	    }
    29	    return true;
    30	  }
    31	  try {
    32	    return storage?.getItem(TWA_SESSION_KEY) === '1';
    33	  } catch {
    34	    return false;
    35	  }
    36	}
