     1	import { DOCUMENT } from '@angular/common';
     2	import { inject, Injectable } from '@angular/core';
     3	
     4	export const PLAY_BILLING_METHOD = 'https://play.google.com/billing';
     5	
     6	/** A tip product as the Play Store sells it in the player's country. */
     7	export interface TipProduct {
     8	  readonly id: string;
     9	  readonly title: string;
    10	  readonly price: string;
    11	}
    12	
    13	export type TipOutcome = 'purchased' | 'cancelled';
    14	
    15	interface DigitalGoodsItem {
    16	  readonly itemId: string;
    17	  readonly title: string;
    18	  readonly price: { readonly currency: string; readonly value: string };
    19	}
    20	
    21	interface DigitalGoodsPurchase {
    22	  readonly itemId: string;
    23	  readonly purchaseToken: string;
    24	}
    25	
    26	/** The part of the Digital Goods API the app's billing bridge answers. */
    27	export interface DigitalGoodsService {
    28	  getDetails(itemIds: string[]): Promise<DigitalGoodsItem[]>;
    29	  listPurchases(): Promise<DigitalGoodsPurchase[]>;
    30	  consume(purchaseToken: string): Promise<void>;
    31	}
    32	
    33	export type DigitalGoodsWindow = Window & {
    34	  getDigitalGoodsService?: (method: string) => Promise<DigitalGoodsService>;
    35	};
    36	
    37	/**
    38	 * Tips inside the Play Store app, sold as consumable Play products through
    39	 * the Digital Goods API and Payment Request.
    40	 *
    41	 * A tip unlocks nothing, so no server checks the purchase: consuming it
    42	 * acknowledges it (Play refunds a purchase nobody acknowledged after three
    43	 * days) and makes the product buyable again.
    44	 */
    45	@Injectable({ providedIn: 'root' })
    46	export class PlayBillingService {
    47	  private readonly window = inject(DOCUMENT)
    48	    .defaultView as DigitalGoodsWindow | null;
    49	  private service: Promise<DigitalGoodsService | null> | null = null;
    50	
    51	  /** The products in the given order, or null without Play Billing. */
    52	  public async loadProducts(
    53	    ids: readonly string[]
    54	  ): Promise<TipProduct[] | null> {
    55	    const service = await this.digitalGoods();
    56	    if (!service) return null;
    57	    try {
    58	      const items = await service.getDetails([...ids]);
    59	      const byId = new Map(items.map((item) => [item.itemId, item]));
    60	      return ids.flatMap((id) => {
    61	        const item = byId.get(id);
    62	        return item
    63	          ? [{ id, title: item.title, price: formatPrice(item.price) }]
    64	          : [];
    65	      });
    66	    } catch {
    67	      return null;
    68	    }
    69	  }
    70	
    71	  public async buy(productId: string): Promise<TipOutcome> {
    72	    const service = await this.digitalGoods();
    73	    if (!service || typeof PaymentRequest === 'undefined') {
    74	      throw new Error('Play Billing is not available');
    75	    }
    76	    const request = new PaymentRequest(
    77	      [{ supportedMethods: PLAY_BILLING_METHOD, data: { sku: productId } }],
    78	      { total: { label: 'Total', amount: { currency: 'EUR', value: '0' } } }
    79	    );
    80	    let response: PaymentResponse;
    81	    try {
    82	      response = await request.show();
    83	    } catch (err) {
    84	      if (err instanceof DOMException && err.name === 'AbortError') {
    85	        return 'cancelled';
    86	      }
    87	      throw err;
    88	    }
    89	    const purchaseToken = (
    90	      response.details as { purchaseToken?: unknown } | undefined
    91	    )?.purchaseToken;
    92	    // The player has paid by now, so a failed consume is no failure to
    93	    // them: `consumePending` on the next start acknowledges the purchase,
    94	    // well inside Play's three days.
    95	    if (typeof purchaseToken === 'string' && purchaseToken) {
    96	      await service.consume(purchaseToken).catch(() => undefined);
    97	    }
    98	    await response.complete('success').catch(() => undefined);
    99	    return 'purchased';
   100	  }
   101	
   102	  /**
   103	   * Consumes the tips an app closed too early left unconsumed, so Play
   104	   * neither refunds them nor refuses to sell the same tip again. Other
   105	   * products are left alone.
   106	   */
   107	  public async consumePending(tipProductIds: readonly string[]): Promise<void> {
   108	    const service = await this.digitalGoods();
   109	    if (!service) return;
   110	    try {
   111	      const purchases = await service.listPurchases();
   112	      await Promise.allSettled(
   113	        purchases
   114	          .filter((purchase) => tipProductIds.includes(purchase.itemId))
   115	          .map((purchase) => service.consume(purchase.purchaseToken))
   116	      );
   117	    } catch {
   118	      // Tried again on the next start.
   119	    }
   120	  }
   121	
   122	  private digitalGoods(): Promise<DigitalGoodsService | null> {
   123	    const pending = (this.service ??= this.connect());
   124	    // A failed connect - the app's bridge not bound yet - is tried again on
   125	    // the next call rather than turning billing off for the session.
   126	    void pending.then((service) => {
   127	      if (!service && this.service === pending) this.service = null;
   128	    });
   129	    return pending;
   130	  }
   131	
   132	  private async connect(): Promise<DigitalGoodsService | null> {
   133	    const connect = this.window?.getDigitalGoodsService;
   134	    if (typeof connect !== 'function') return null;
   135	    try {
   136	      return await connect.call(this.window, PLAY_BILLING_METHOD);
   137	    } catch {
   138	      return null;
   139	    }
   140	  }
   141	}
   142	
   143	function formatPrice(price: DigitalGoodsItem['price']): string {
   144	  try {
   145	    return new Intl.NumberFormat(undefined, {
   146	      style: 'currency',
   147	      currency: price.currency,
   148	    }).format(Number(price.value));
   149	  } catch {
   150	    return `${price.value} ${price.currency}`;
   151	  }
   152	}
